-- ==========================================
-- 2. 空き家テーブル (houses) の作成とデータ投入
-- ==========================================
CREATE TABLE houses (
    id INT PRIMARY KEY,
    title VARCHAR(100),
    municipality VARCHAR(50),
    address TEXT,
    price INT,
    layout VARCHAR(50),
    floors INT,
    land_area_m2 NUMERIC,
    building_area_m2 NUMERIC,
    tsubo NUMERIC,
    tsubo_unit_price_maruen NUMERIC,
    structure VARCHAR(50),
    built_year VARCHAR(50),
    renovation_cost_est INT,
    features TEXT,
    latitude NUMERIC,
    longitude NUMERIC
);

